    if (existing) tagIds.push(existing.id);
    else {
      const createRes = await $http.post(`${wpBase}/wp-json/wp/v2/tags`, { name: tagName, slug }, { headers: { 'Authorization': auth, 'Content-Type': 'application/json' } });
      if (createRes.data?.id) tagIds.push(createRes.data.id);
